from functools import lru_cache


@lru_cache(maxsize=None)
def fibonacci(n):
    if n < 0:
        raise ValueError("n must not be negative")
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)


def first_numbers(count):
    numbers = []
    for index in range(count):
        numbers.append(fibonacci(index))
    return numbers


def is_fibonacci(value):
    index = 0
    while fibonacci(index) < value:
        index += 1
    return fibonacci(index) == value


def print_table(count):
    for index, number in enumerate(first_numbers(count)):
        print(f"{index:>3} | {number:>12}")


if __name__ == "__main__":
    print_table(20)
    print(is_fibonacci(144))
    print(is_fibonacci(145))
